solutionCode:
fun safeGet(list: List<Int>, index: Int): Int? {
    return try {
        list[index]
    } catch (e: IndexOutOfBoundsException) {
        null
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testValidIndex() {
        Assert.assertEquals(20, safeGet(listOf(10, 20, 30), 1))
    }

    @Test
    fun testFirstElement() {
        Assert.assertEquals(10, safeGet(listOf(10, 20, 30), 0))
    }

    @Test
    fun testIndexTooLarge() {
        Assert.assertNull(safeGet(listOf(10, 20, 30), 5))
    }

    @Test
    fun testNegativeIndex() {
        Assert.assertNull(safeGet(listOf(10, 20, 30), -1))
    }

    @Test
    fun testEmptyList() {
        Assert.assertNull(safeGet(emptyList(), 0))
    }
}
